{
  "probability": 0.28,
  "range_low": 0.18,
  "range_high": 0.42,
  "summary": [
    "Opposition consolidation around the TISZA anti-Orbán bloc raises the odds of a 133+ seat outcome, challenging the incumbent.",
    "Turnout dynamics favoring anti-government voters and near-threshold seat projections create a meaningful tail risk toward a two-thirds outcome.",
    "Electoral-system biases and district-level design dampen the likelihood of a clean 2/3 majority despite momentum signals.",
    "Poll dispersion and potential fragmentation keep the probability in a moderate, uncertain range rather than a base-case."
  ],
  "confidence": "medium",
  "narrative": "Starting from a modest baseline probability, credible signs of opposition unity and mobilization push the odds upward, while systemic biases and poll volatility pull them back. The result is a calibrated estimate in the high-20s with a broad uncertainty window, reflecting genuine tail risk but no strong consensus for a near-certainty 2/3 majority.",
  "justification": {
    "anchor": {
      "probability": 0.22,
      "basis": "Reference class probability for achieving a 2/3 majority under Hungary's current mixed-member system, anchored on historical frequencies and current signals; this serves as a conservative baseline given ongoing polling divergence."
    },
    "factor_updates": [
      {
        "factor": "Opposition consolidation around TISZA (anti-Orbán bloc)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Credible polling and public-messaging indicate reduced vote-splitting and a more coherent anti-government platform, increasing the chance to reach 133+ seats if momentum persists."
      },
      {
        "factor": "Turnout dynamics favoring anti-government opposition",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Higher turnout among opposition-leaning voters could widen margins and tilt seat counts toward an anti-Fidesz bloc."
      },
      {
        "factor": "Near-threshold seat projections",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Seat-models clustering near 133 suggests small vote swings or turnout shifts could cross the threshold."
      },
      {
        "factor": "Electoral-system bias and district changes",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "The mixed-member system (106 districts + 93 list seats) and district-level biases tend to dampen large swings into a 2/3 majority even with broad support."
      },
      {
        "factor": "Potential fragmentation from smaller entrants",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Entrants threatening to cross thresholds can siphon votes, complicating a clean 133+ seat tally for any one bloc."
      }
    ],
    "synthesis_rationale": "With a 0.22 anchor, upward pushes from opposition unity, turnout advantages, and proximate seat forecasts are tempered by structural dampeners from the electoral system and fragmentation risk. The synthesis yields a central estimate in the high-20s and acknowledges a wide confidence interval reflecting polling divergence and dynamic political conditions."
  }
}
